/* =========================================================
   samples.js — 内嵌的真实录音（base64 MP3）

   为什么内嵌而不是 fetch 文件：
     项目要求双击 index.html 就能用（file:// 协议），
     而 file:// 下 fetch 本地文件会被 CORS 拦死；
     把 MP3 以 data URI 内嵌后，fetch + decodeAudioData 在
     任何协议下都能工作。

   素材：
     assets/audio/dog_barking.mp3   1.62 s  两声犬吠，48 kHz 立体声（近乎单声道）
     assets/audio/footsteps.mp3     5.25 s  八步行走，48 kHz，含一次自然停顿

   换成自己的录音：把 MP3 做 base64 后替换下面两个字符串即可
   （Node 一行：fs.readFileSync(p).toString('base64')）。
   ========================================================= */
window.SALab = window.SALab || {};
window.SALab.SAMPLE_MP3 = {
  bark: 'data:audio/mpeg;base64,',
  steps: 'data:audio/mpeg;base64,'
};
